CREATE TABLE media_assets (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),object_key text NOT NULL UNIQUE,original_name text NOT NULL,mime_type text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>0),width int,height int,
 kind text NOT NULL CHECK(kind IN ('image','video','document')),visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('public','private')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready','archived')),
 alt_text text,caption text,collection text,source_credit text,uploaded_by_staff_id uuid REFERENCES staff_users,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE destinations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug varchar(180) NOT NULL UNIQUE,name varchar(160) NOT NULL,description text NOT NULL DEFAULT '',country_code char(2) NOT NULL DEFAULT 'VN',latitude numeric(9,6) CHECK(latitude BETWEEN -90 AND 90),longitude numeric(9,6) CHECK(longitude BETWEEN -180 AND 180),cover_media_id uuid REFERENCES media_assets,seo_title text,seo_description text,published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tour_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug varchar(180) NOT NULL UNIQUE,name varchar(120) NOT NULL,description text NOT NULL DEFAULT '',sort_order int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tours(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug varchar(180) NOT NULL UNIQUE,code varchar(32) NOT NULL UNIQUE,title varchar(200) NOT NULL,summary text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',region text NOT NULL CHECK(region IN ('domestic','international')),audience text NOT NULL CHECK(audience IN ('general','school','company')),
 duration_days smallint NOT NULL CHECK(duration_days>0),duration_nights smallint NOT NULL CHECK(duration_nights>=0),origin_name text NOT NULL,transport text NOT NULL,difficulty text NOT NULL DEFAULT 'easy' CHECK(difficulty IN ('easy','moderate','hard')),hotel_summary text,included text NOT NULL DEFAULT '',excluded text NOT NULL DEFAULT '',cancellation_policy text NOT NULL DEFAULT '',preparation_guide text,age_policy jsonb NOT NULL DEFAULT '{}',
 status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),featured boolean NOT NULL DEFAULT false,cover_media_id uuid REFERENCES media_assets,poster_media_id uuid REFERENCES media_assets,poster_revision int NOT NULL DEFAULT 1 CHECK(poster_revision>0),poster_verified_at timestamptz,poster_verified_by uuid REFERENCES staff_users,seo_title text,seo_description text,is_demo boolean NOT NULL DEFAULT true,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX tours_status ON tours(status,region,published_at);
CREATE TABLE tour_destinations(tour_id uuid NOT NULL REFERENCES tours ON DELETE CASCADE,destination_id uuid NOT NULL REFERENCES destinations,sort_order int NOT NULL DEFAULT 0,PRIMARY KEY(tour_id,destination_id));
CREATE INDEX tour_destinations_destination ON tour_destinations(destination_id,tour_id);
CREATE TABLE tour_category_links(tour_id uuid NOT NULL REFERENCES tours ON DELETE CASCADE,category_id uuid NOT NULL REFERENCES tour_categories,PRIMARY KEY(tour_id,category_id));
CREATE TABLE tour_days(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tour_id uuid NOT NULL REFERENCES tours ON DELETE CASCADE,day_number smallint NOT NULL CHECK(day_number>0),title text NOT NULL,body text NOT NULL,meals text,accommodation text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tour_id,day_number));
CREATE TABLE tour_stops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tour_id uuid NOT NULL REFERENCES tours ON DELETE CASCADE,day_number smallint NOT NULL CHECK(day_number>0),sort_order int NOT NULL,name text NOT NULL,latitude numeric(9,6) NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude numeric(9,6) NOT NULL CHECK(longitude BETWEEN -180 AND 180),description text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tour_id,day_number,sort_order));
CREATE TABLE tour_media(tour_id uuid NOT NULL REFERENCES tours ON DELETE CASCADE,media_id uuid NOT NULL REFERENCES media_assets,caption text,sort_order int NOT NULL DEFAULT 0,PRIMARY KEY(tour_id,media_id));
CREATE TABLE departures(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tour_id uuid NOT NULL REFERENCES tours,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,sales_close_at timestamptz NOT NULL,capacity int NOT NULL CHECK(capacity>0),held_seats int NOT NULL DEFAULT 0 CHECK(held_seats>=0),confirmed_seats int NOT NULL DEFAULT 0 CHECK(confirmed_seats>=0),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','open','closed','cancelled','completed')),price_version int NOT NULL DEFAULT 1 CHECK(price_version>0),deposit_bps int NOT NULL CHECK(deposit_bps BETWEEN 1 AND 10000),balance_due_at timestamptz NOT NULL,currency char(3) NOT NULL DEFAULT 'VND' CHECK(currency='VND'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tour_id,starts_at),CHECK(starts_at<ends_at),CHECK(sales_close_at<=starts_at),CHECK(balance_due_at<starts_at),CHECK(held_seats+confirmed_seats<=capacity)
);
CREATE INDEX departures_tour ON departures(tour_id,starts_at);CREATE INDEX departures_status ON departures(status,starts_at);
CREATE TABLE departure_prices(departure_id uuid NOT NULL REFERENCES departures ON DELETE CASCADE,passenger_type text NOT NULL CHECK(passenger_type IN ('adult','child','infant')),unit_price bigint NOT NULL CHECK(unit_price BETWEEN 0 AND 1000000000000),seats_per_person smallint NOT NULL CHECK(seats_per_person IN (0,1)),min_age int NOT NULL CHECK(min_age>=0),max_age_exclusive int CHECK(max_age_exclusive>min_age),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(departure_id,passenger_type));
CREATE TABLE departure_surcharges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),departure_id uuid NOT NULL REFERENCES departures ON DELETE CASCADE,code varchar(40) NOT NULL,label text NOT NULL,amount bigint NOT NULL CHECK(amount BETWEEN 0 AND 1000000000000),unit text NOT NULL CHECK(unit IN ('per_booking','per_person')),required boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(departure_id,code));
CREATE TABLE pricing_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),departure_id uuid NOT NULL REFERENCES departures,guest_session_id uuid REFERENCES guest_sessions,created_by_staff_id uuid REFERENCES staff_users,price_version int NOT NULL,counts jsonb NOT NULL,selected_surcharge_codes jsonb NOT NULL,pricing_snapshot jsonb NOT NULL,total_amount bigint NOT NULL CHECK(total_amount>0),deposit_amount bigint NOT NULL CHECK(deposit_amount>0 AND deposit_amount<=total_amount),settings_version int NOT NULL,settings_snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK((guest_session_id IS NOT NULL)::int+(created_by_staff_id IS NOT NULL)::int=1));
CREATE INDEX pricing_quotes_expiry ON pricing_quotes(expires_at);
CREATE TABLE post_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,excerpt text NOT NULL DEFAULT '',body text NOT NULL DEFAULT '',category_id uuid REFERENCES post_categories,cover_media_id uuid REFERENCES media_assets,author_id uuid NOT NULL REFERENCES staff_users,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),seo_title text,seo_description text,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE post_tags(post_id uuid NOT NULL REFERENCES posts ON DELETE CASCADE,tag_id uuid NOT NULL REFERENCES tags,PRIMARY KEY(post_id,tag_id));
CREATE TABLE pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,body text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),seo_title text,seo_description text,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE banners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,media_id uuid NOT NULL REFERENCES media_assets,target_url text,placement text NOT NULL,sort_order int NOT NULL DEFAULT 0,starts_at timestamptz,ends_at timestamptz,active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE TABLE faqs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic text NOT NULL,tour_id uuid REFERENCES tours,question text NOT NULL,answer text NOT NULL,sort_order int NOT NULL DEFAULT 0,published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tour_id uuid REFERENCES tours,group_type text CHECK(group_type IN ('school','company')),display_name text NOT NULL,organization_name text,rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5),body text NOT NULL,media_id uuid REFERENCES media_assets,source text NOT NULL,is_demo boolean NOT NULL DEFAULT true,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reviewed_by uuid REFERENCES staff_users,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
